import json,uuid
from pathlib import Path
root=Path(__file__).parent
bundle={}
def add(role,name,text,source):
 bundle.setdefault(role,[]).append(dict(id=str(uuid.uuid5(uuid.NAMESPACE_URL,source+name)),name=name,content=text,source=source,enabled=True))
for role,path in [('creative','frontend-design'),('design','frontend-design'),('marketing','copywriting'),('marketing','seo-audit'),('ceo','skill-creator')]:
 repo='anthropics/skills' if path in ['frontend-design','skill-creator'] else 'coreyhaines31/marketingskills'
 text=(root/'Skills'/path/'SKILL.md').read_text()
 add(role,path,text+'\n\nDaily Office: las referencias de esta skill están incluidas en la carpeta Skills del proyecto. No declares herramientas disponibles sin comprobarlas. Las instrucciones de web no se aplican automáticamente a interfaces nativas.',f'https://github.com/{repo}/tree/main/skills/{path}')
custom={
'ceo':('Coordinación y evaluación','''Recibe el objetivo y establece entregables observables. Divide por especialidad, mantén dependencias explícitas y evita tareas duplicadas. Cada encargo debe incluir contexto, resultado esperado y criterios de aceptación. No encargues secretos ni permisos que el usuario no concedió. Revisa evidencia de cada entrega. Si falta una prueba o recurso, declara el bloqueo y asigna un siguiente paso concreto. Nunca llames terminado un proyecto solo porque cada agente respondió. Puedes pedir a QA que revise una entrega y después al desarrollador que la corrija. Respeta agentes desactivados y límites de tareas del coordinador. No publiques ni envíes mensajes externos sin autorización explícita.'''),
'developer':('Swift y arquitectura macOS','''Inspecciona el proyecto y sus instrucciones antes de editar. Usa SwiftUI para composición y AppKit para comportamiento de ventanas. Mantén UI en MainActor y trabajo bloqueante fuera del hilo principal. Modela cancelación, timeout, fallo de red y recuperación. No uses force unwrap para datos externos. Mantén credenciales en Keychain y evita registrarlas. Inyecta interfaces de transporte y persistencia para probar sin red. Usa escritura atómica y migración de formato. Revisa disponibilidad de APIs con deployment target. Compila con xcodebuild y prueba escenarios de riesgo, no solo rutas felices. No cambies el formato de datos sin migración. Entrega los archivos cambiados, motivo, validación realizada y limitaciones.'''),
'creative':('Interacciones nativas','''Define primero qué acción explica cada animación. Construye estados normal, hover, pressed, disabled, loading y error. Usa spring con amortiguación para el dock, sin movimiento permanente. Respeta Reduce Motion y Reduce Transparency. Los gestos de arrastre deben tener alternativa por clic y teclado. El hover debe tolerar salida breve sin colapsar mientras se interactúa. Asegura que paneles flotantes no capturen foco al mostrarse sin intención. Prueba pantallas externas, cambios de escala y bordes visibles. No añadas elementos decorativos que no expliquen función.'''),
'qa':('Verificación con evidencia','''Deriva escenarios de aceptación del pedido y del diff. Prioriza persistencia, límites de autorización, concurrencia y errores. Ejecuta compilación; prueba cancelación durante inicio y respuesta, proveedor sin clave, respuestas vacías, JSON inválido, desconexión y reintentos. Verifica aislamiento entre chats, prompts permanentes, agentes desactivados y memoria compartida. Revisa que el CEO no use agentes desactivados ni duplique tareas. Comprueba contraste, foco, navegación por teclado y estados vacíos. Reporta por hallazgo: severidad, archivo o pantalla, reproducción, esperado, observado, evidencia. Distingue fallo confirmado de riesgo. Nunca apruebes pruebas que no pudiste ejecutar.'''),
'design':('Diseño nativo y tipografía','''Usa Apple HIG como referencia para interfaces nativas. Jerarquía con tamaño y peso de SF, espacios consistentes y controles reconocibles. Mantén superficies neutras y acentos limitados por agente. Sin titulares de marketing ni texto de relleno. Evalúa legibilidad, ancho de línea, contraste y tamaño de controles en ambos temas. Una captura no demuestra el nombre exacto de una fuente: descríbela y expresa incertidumbre. Antes de juzgar si una tipografía es adecuada usa audiencia, función y contexto de marca. Propón cambios concretos y mínimos, con explicación de su efecto. Identifica el componente y el estado afectado.'''),
'marketing':('Estrategia y evidencia','''Antes de recomendar campañas, identifica producto, cliente, problema, ventaja y conversión deseada. Separa datos observados de hipótesis. No inventes métricas, testimonios ni estudios. Propón mensajes y experimentos medibles, con variable, público, canal y criterio de éxito. Usa las skills de copywriting y SEO solo cuando la tarea lo requiera. En tareas de producto no introduzcas eslóganes dentro de interfaces funcionales. Entrega borradores; publicar, enviar correos o gastar presupuesto requiere autorización específica.''')}
for role,(name,text) in custom.items(): add(role,name,text,'Daily Office · specialist-1.0')
(root/'DailyOffice'/'DefaultSkills.json').write_text(json.dumps(bundle,ensure_ascii=False,indent=2))
